use glam::DVec3;use ingetrazo_gui::{IngeTrazoApp,navigation::{self,Mode}};
fn frame(app:&mut IngeTrazoApp,ctx:&egui::Context,time:f64,events:Vec<egui::Event>){let _=ctx.run(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(800.,600.))),time:Some(time),focused:true,events,..Default::default()},|ctx|{egui::CentralPanel::default().frame(egui::Frame::none()).show(ctx,|ui|{let rect=ui.available_rect_before_wrap();let response=ui.allocate_rect(rect,egui::Sense::click_and_drag());navigation::input(app,ui,rect,&response);});});}
fn button(pos:egui::Pos2,button:egui::PointerButton,pressed:bool)->egui::Event{egui::Event::PointerButton{pos,button,pressed,modifiers:egui::Modifiers::NONE}}
fn main(){let mut rows=vec![];for name in ["split-drag","move-release-one-frame","press-move-release-one-frame","six-pixel-click"]{
let mut app=IngeTrazoApp::new();app.camera.distance=10.;app.camera.aspect=800./600.;app.camera.target=DVec3::ZERO;app.camera.set_standard_view(ingetrazo_core::camera::StandardView::Top);app.activate_navigation(Mode::Position);let ctx=egui::Context::default();frame(&mut app,&ctx,0.,vec![]);let a=egui::pos2(430.,330.);let b=if name=="six-pixel-click"{egui::pos2(436.,330.)}else{egui::pos2(470.,350.)};let press=vec![egui::Event::PointerMoved(a),button(a,egui::PointerButton::Primary,true)];let motion=egui::Event::PointerMoved(b);let release=button(b,egui::PointerButton::Primary,false);
if name=="press-move-release-one-frame"{frame(&mut app,&ctx,0.01,press.into_iter().chain([motion,release]).collect());}else{frame(&mut app,&ctx,0.01,press);if name=="move-release-one-frame"{frame(&mut app,&ctx,0.02,vec![motion,release]);}else{frame(&mut app,&ctx,0.02,vec![motion]);frame(&mut app,&ctx,0.03,vec![release]);}}
rows.push(serde_json::json!({"name":name,"eye":app.camera.eye().to_array(),"forward":app.camera.forward().to_array(),"mode":format!("{:?}",app.navigation.mode),"undo":app.undo_stack.len()}));}println!("{}",serde_json::json!({"cases":rows}));}
